test('compareVersions orders core, prerelease, numeric, and ASCII identifiers', () => {
  const ordered = [
    '1.0.0-alpha',
    '1.0.0-alpha.2',
    '1.0.0-alpha.10',
    '1.0.0-alpha.10.a',
    '1.0.0-alpha.a',
    '1.0.0-Alpha',
    '1.0.0-alpha-z',
    '1.0.0'
  ];
  for (let i = 0; i < ordered.length - 1; i++) {
    assert.equal(compareVersions(ordered[i], ordered[i + 1]), -1);
  }
  assert.equal(compareVersions('1.0.0-999999999999999999999999999999', '1.0.0-1000000000000000000000000000000'), -1);
  assert.equal(compareVersions('2.0.0-zz', '1.999.999'), 1);
});

