test('parseVersion rejects malformed prerelease and build metadata', () => {
  for (const version of [
    '1.2.3-',
    '1.2.3-alpha..1',
    '1.2.3-alpha_1',
    '1.2.3-01',
    '1.2.3-alpha+build',
