import test from 'node:test';
import assert from 'node:assert/strict';
import {highest} from '/workspace/src/index.mjs';

test('highest inherits prerelease ordering and does not mutate input', () => {
  const versions = ['1.0.0', '2.0.0-beta', '2.0.0-alpha', '1.0.0-z'];
  const original = [...versions];
  assert.equal(highest(versions), '2.0.0-beta');
